"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2289],{85567:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"link","href":"/endless-journey-docs/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/endless-journey-docs/docs/getting-started/toolchain","label":"Toolchain & Build","docId":"getting-started/toolchain","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/getting-started/maintaining-docs","label":"Maintaining These Docs","docId":"getting-started/maintaining-docs","unlisted":false}],"collapsible":true,"href":"/endless-journey-docs/docs/getting-started"},{"type":"category","label":"Architecture","items":[{"type":"link","href":"/endless-journey-docs/docs/architecture/overview","label":"Architecture Overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/architecture/backbone","label":"Backbone Modules","docId":"architecture/backbone","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/architecture/authority-pattern","label":"Authority Pattern","docId":"architecture/authority-pattern","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/endless-journey-docs/docs/architecture"},{"type":"category","label":"Systems","items":[{"type":"category","label":"Core Loop","items":[{"type":"link","href":"/endless-journey-docs/docs/systems/placement","label":"Placement","docId":"systems/placement","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/placeable-actions","label":"Placeable Actions (Stash / Move)","docId":"systems/placeable-actions","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/junk","label":"Junk","docId":"systems/junk","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/grabhook","label":"GrabHook","docId":"systems/grabhook","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/proximity-pickup","label":"Proximity Pickup","docId":"systems/proximity-pickup","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/shredder","label":"Shredder","docId":"systems/shredder","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/workbench-crafting","label":"Workbench Crafting","docId":"systems/workbench-crafting","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/research-bench","label":"Research Bench","docId":"systems/research-bench","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Train","items":[{"type":"link","href":"/endless-journey-docs/docs/systems/train-fuel","label":"Train Fuel","docId":"systems/train-fuel","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/train-shield","label":"Train Shield","docId":"systems/train-shield","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/cannon","label":"Cannon","docId":"systems/cannon","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/events-orchestrator","label":"Events Orchestrator","docId":"systems/events-orchestrator","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/jump-drive","label":"Jump Drive","docId":"systems/jump-drive","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/disruption","label":"Disruption / Maintenance","docId":"systems/disruption","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Combat","items":[{"type":"link","href":"/endless-journey-docs/docs/systems/weapons","label":"Weapons","docId":"systems/weapons","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/enemy-combat","label":"Enemy Combat","docId":"systems/enemy-combat","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/enemy-spawner","label":"Enemy Spawner","docId":"systems/enemy-spawner","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/health","label":"Health","docId":"systems/health","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/damage-numbers","label":"Damage Numbers","docId":"systems/damage-numbers","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Player","items":[{"type":"link","href":"/endless-journey-docs/docs/systems/stamina-sprint","label":"Stamina & Sprint","docId":"systems/stamina-sprint","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/camera","label":"Camera","docId":"systems/camera","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/settings","label":"Settings (User Preferences)","docId":"systems/settings","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Progression & Economy","items":[{"type":"link","href":"/endless-journey-docs/docs/systems/progression","label":"Progression (XP & Level)","docId":"systems/progression","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/economy","label":"Economy (Coins)","docId":"systems/economy","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/quests","label":"Quests (Daily & Weekly)","docId":"systems/quests","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/battle-pass","label":"Battle Pass (Monthly)","docId":"systems/battle-pass","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/perks","label":"Perks","docId":"systems/perks","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Platform","items":[{"type":"link","href":"/endless-journey-docs/docs/systems/sound","label":"Sound","docId":"systems/sound","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/notifications","label":"Notifications","docId":"systems/notifications","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/systems/session-rejoin","label":"Party Lock + Mid-Run Rejoin","docId":"systems/session-rejoin","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true,"href":"/endless-journey-docs/docs/systems"},{"type":"category","label":"How-To Playbooks","items":[{"type":"category","label":"Backbone","items":[{"type":"link","href":"/endless-journey-docs/docs/playbooks/add-packet","label":"Add a Network Packet (Client \u2194 Server Channel)","docId":"playbooks/add-packet","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/add-signal","label":"Add an In-Process Signal","docId":"playbooks/add-signal","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Core Loop","items":[{"type":"link","href":"/endless-journey-docs/docs/playbooks/add-placeable","label":"Add a New Placeable Item","docId":"playbooks/add-placeable","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/adjust-junk-flow","label":"Adjust Junk Flow","docId":"playbooks/adjust-junk-flow","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-shredder","label":"Tune Shredder Economy","docId":"playbooks/tune-shredder","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/enable-stash-move","label":"Enable Stash / Move on a Placeable","docId":"playbooks/enable-stash-move","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/update-build-ui","label":"Update Build Mode UI/UX","docId":"playbooks/update-build-ui","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-research-bench","label":"Tune Research Bench","docId":"playbooks/tune-research-bench","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Player","items":[{"type":"link","href":"/endless-journey-docs/docs/playbooks/change-sprint","label":"Change Sprint Behavior","docId":"playbooks/change-sprint","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-stamina","label":"Tune Stamina Economy","docId":"playbooks/tune-stamina","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Progression & Economy","items":[{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-quests","label":"Tune Quests","docId":"playbooks/tune-quests","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-battle-pass","label":"Tune Battle Pass","docId":"playbooks/tune-battle-pass","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-perks","label":"Tune Perks","docId":"playbooks/tune-perks","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/tune-perk-unlocks","label":"Tune Perk Unlocks","docId":"playbooks/tune-perk-unlocks","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Platform","items":[{"type":"link","href":"/endless-journey-docs/docs/playbooks/add-sound","label":"Add a Sound (SFX / Music / Ambience)","docId":"playbooks/add-sound","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/playbooks/add-notification","label":"Add / Show a Toast Notification","docId":"playbooks/add-notification","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true,"href":"/endless-journey-docs/docs/playbooks"},{"type":"category","label":"Reference","items":[{"type":"link","href":"/endless-journey-docs/docs/reference/networking-map","label":"Networking Map","docId":"reference/networking-map","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/reference/signals-map","label":"Signals Map","docId":"reference/signals-map","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/reference/config-map","label":"Config Map","docId":"reference/config-map","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/reference/janitor-patterns","label":"Janitor Patterns","docId":"reference/janitor-patterns","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/reference/motionmaster-cheatsheet","label":"MotionMaster Cheatsheet","docId":"reference/motionmaster-cheatsheet","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/reference/dropdown-widget","label":"Dropdown widget","docId":"reference/dropdown-widget","unlisted":false},{"type":"link","href":"/endless-journey-docs/docs/reference/dependencies","label":"Dependencies","docId":"reference/dependencies","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/endless-journey-docs/docs/reference"}]},"docs":{"architecture/authority-pattern":{"id":"architecture/authority-pattern","title":"Authority Pattern","description":"Client Predicts / Server Authoritative","sidebar":"docs"},"architecture/backbone":{"id":"architecture/backbone","title":"Backbone Modules","description":"These seven modules are the cross-cutting infrastructure that everything else in Endless Journey wires through. Understanding them is prerequisite to safely modifying any system.","sidebar":"docs"},"architecture/overview":{"id":"architecture/overview","title":"Architecture Overview","description":"Endless Journey uses a three-layer runtime architecture: Client, Shared, and Server. Network traffic between the client and server always flows through typed Packets; in-process events on the client flow through the Signals event bus.","sidebar":"docs"},"getting-started/maintaining-docs":{"id":"getting-started/maintaining-docs","title":"Maintaining These Docs","description":"Where Content Lives","sidebar":"docs"},"getting-started/toolchain":{"id":"getting-started/toolchain","title":"Toolchain & Build","description":"Endless Journey uses a small, pinned toolchain. All tools are declared in rokit.toml and managed by Rokit.","sidebar":"docs"},"intro":{"id":"intro","title":"Introduction","description":"Endless Journey is a Roblox game inspired by Void Train, built with Rojo. Luau source lives under src/ and syncs live into the Roblox DataModel via default.project.json. This site is the maintenance and architecture reference for everyone working on the project.","sidebar":"docs"},"playbooks/add-notification":{"id":"playbooks/add-notification","title":"Add / Show a Toast Notification","description":"Goal: Surface a toast message to the local player \u2014 success confirmations, warnings, errors, or informational messages.","sidebar":"docs"},"playbooks/add-packet":{"id":"playbooks/add-packet","title":"Add a Network Packet (Client \u2194 Server Channel)","description":"Goal: Add a new client-to-server or server-to-client communication channel.","sidebar":"docs"},"playbooks/add-placeable":{"id":"playbooks/add-placeable","title":"Add a New Placeable Item","description":"Goal: Make a new item appear in the build-mode palette and be placeable by players.","sidebar":"docs"},"playbooks/add-signal":{"id":"playbooks/add-signal","title":"Add an In-Process Signal","description":"Goal: Let two or more scripts on the same side (client-only or server-only) communicate without direct coupling \u2014 UI intents, gameplay events, or state change notifications.","sidebar":"docs"},"playbooks/add-sound":{"id":"playbooks/add-sound","title":"Add a Sound (SFX / Music / Ambience)","description":"Goal: Add a new game sound \u2014 one-shot SFX, positional SFX, looped SFX, a music playlist track, or an ambience bed \u2014 without ad-hoc Sound instances.","sidebar":"docs"},"playbooks/adjust-junk-flow":{"id":"playbooks/adjust-junk-flow","title":"Adjust Junk Flow","description":"Goal: Tune how frequently junk spawns, how long it survives, how fast it moves, or how tier/type probabilities are weighted.","sidebar":"docs"},"playbooks/change-sprint":{"id":"playbooks/change-sprint","title":"Change Sprint Behavior","description":"Goal: Adjust sprint speed, FOV curve, keybinds, or sprint state-machine logic.","sidebar":"docs"},"playbooks/enable-stash-move":{"id":"playbooks/enable-stash-move","title":"Enable Stash / Move on a Placeable","description":"Goal: Let players return a placed item to their Backpack (Stash) or immediately re-equip it (Move) from its in-world GUI.","sidebar":"docs"},"playbooks/tune-battle-pass":{"id":"playbooks/tune-battle-pass","title":"Tune Battle Pass","description":"Goal: Launch the premium subscription, edit the tier track for a new month, fill in milestone item rewards, or add Scope = \\"Season\\" quests to feed the pass.","sidebar":"docs"},"playbooks/tune-perk-unlocks":{"id":"playbooks/tune-perk-unlocks","title":"Tune Perk Unlocks","description":"Goal: Choose which perks are free starters, set a perk\'s one-time coin cost / level gate, and reason about how those choices interact with respec refunds and the schema migration.","sidebar":"docs"},"playbooks/tune-perks":{"id":"playbooks/tune-perks","title":"Tune Perks","description":"Goal: Adjust perk values, add a new perk, or wire a perk to a new consumer.","sidebar":"docs"},"playbooks/tune-quests":{"id":"playbooks/tune-quests","title":"Tune Quests","description":"Goal: Add a quest, adjust how many quests rotate in per period, or shift the daily/weekly reset boundary.","sidebar":"docs"},"playbooks/tune-research-bench":{"id":"playbooks/tune-research-bench","title":"Tune Research Bench","description":"Goal: Adjust Research Bench node costs/durations, fuel/queue/refund constants, or add a new node.","sidebar":"docs"},"playbooks/tune-shredder":{"id":"playbooks/tune-shredder","title":"Tune Shredder Economy","description":"Goal: Adjust hold duration, arc animation, anti-exploit tolerances, or material yield for the Workbench Shredder.","sidebar":"docs"},"playbooks/tune-stamina":{"id":"playbooks/tune-stamina","title":"Tune Stamina Economy","description":"Goal: Adjust how fast stamina drains, regenerates, or how buff pickups feel.","sidebar":"docs"},"playbooks/update-build-ui":{"id":"playbooks/update-build-ui","title":"Update Build Mode UI/UX","description":"Goal: Change build-mode icon assets, ghost visuals, grid overlay appearance, or the button-to-signal mapping in BuildModeGuiController.","sidebar":"docs"},"reference/config-map":{"id":"reference/config-map","title":"Config Map","description":"Update this table in the same commit when you add a config module \u2014 see also the relevant system playbook linked in each row.","sidebar":"docs"},"reference/dependencies":{"id":"reference/dependencies","title":"Dependencies","description":"This page links out to upstream docs for every third-party and vendored dependency","sidebar":"docs"},"reference/dropdown-widget":{"id":"reference/dropdown-widget","title":"Dropdown widget","description":"ReplicatedStorage/SharedModules/Gui/Dropdown.luau \u2014 a reusable client dropdown/","sidebar":"docs"},"reference/janitor-patterns":{"id":"reference/janitor-patterns","title":"Janitor Patterns","description":"Janitor (howmanysmall/janitor) is the project\'s sole cleanup primitive.","sidebar":"docs"},"reference/motionmaster-cheatsheet":{"id":"reference/motionmaster-cheatsheet","title":"MotionMaster Cheatsheet","description":"MotionMaster is the project\'s animation library, vendored at","sidebar":"docs"},"reference/networking-map":{"id":"reference/networking-map","title":"Networking Map","description":"Update this table in the same commit when you add a packet \u2014 see also the Add a Packet playbook.","sidebar":"docs"},"reference/signals-map":{"id":"reference/signals-map","title":"Signals Map","description":"Update this table in the same commit when you add a signal \u2014 see also the Add a Signal playbook.","sidebar":"docs"},"systems/battle-pass":{"id":"systems/battle-pass","title":"Battle Pass (Monthly)","description":"A monthly, ProfileStore-backed progression track layered on top of the quest system\'s EXP feed. A single 60-tier track carries two reward rows \u2014 Free (everyone) and Premium (active Roblox subscribers) \u2014 and resets on a calendar-month boundary shared by every player and server. Structured shared/server/client like Quests and Perks. No GUI ships this cycle.","sidebar":"docs"},"systems/camera":{"id":"systems/camera","title":"Camera","description":"A fully script-owned third-person camera. CameraController sets Camera.CameraType = Enum.CameraType.Scriptable and computes Camera.CFrame every frame from yaw/pitch/distance state, rather than decorating Roblox\'s default Custom camera. Mouse-look, scroll zoom, wall occlusion, and character-facing are all one render step in one script; a small stateless module (CameraRig) does the CFrame math. The system is client-only \u2014 there is no server component.","sidebar":"docs"},"systems/cannon":{"id":"systems/cannon","title":"Cannon","description":"A grid-placeable, manned cannon that fires server-authoritative explosive arc shells. It hosts the Cannon Damage party perk (CannonDamageBonus) and completes perk Spec 5. The cannon reuses the weapon stack (FastCast2 + ServerProjectile + CombatService.ApplyAOE) and the placement stack (PlaceableItems \u2192 PlacedObjects); the server fires from its own muzzle CFrame, so client aim is never trusted for damage.","sidebar":"docs"},"systems/damage-numbers":{"id":"systems/damage-numbers","title":"Damage Numbers","description":"DamageNumbers is a client-only, render-only module that shows floating world-space damage numbers above targets. It does not compute or apply damage \u2014 damage stays server-authoritative (see Weapons \u2192 CombatService). Any client code calls it with a position and an amount; the settings menu toggles it on/off.","sidebar":"docs"},"systems/disruption":{"id":"systems/disruption","title":"Disruption / Maintenance","description":"On server shutdown or maintenance the game notifies players, force-saves their persisted data, and teleports them to the lobby place. Transient run state (fuel, shield, health, stamina, in-progress research, placed items, ammo, backpack junk) intentionally resets \u2014 session-state recovery is out of scope. DisruptionCoordinator is the server-side authority; ProfileStore session-locking is the correctness backstop underneath it.","sidebar":"docs"},"systems/economy":{"id":"systems/economy","title":"Economy (Coins)","description":"Server-authoritative coin wallet persisted with ProfileStore, in a profile separate from XP. The balance is shared across the lobby and gameplay places.","sidebar":"docs"},"systems/enemy-combat":{"id":"systems/enemy-combat","title":"Enemy Combat","description":"Server-authoritative combat for spawned enemies, driven by a single centralized AI director rather than a script-per-enemy. EnemyBrain ticks every armed enemy at a fixed 10 Hz, deciding movement and firing as two independent concerns each tick. Enemy weapons reuse the exact same damage layer as player weapons \u2014 FastCast2 projectiles, ServerProjectile lobs, WeaponValidation melee hitboxes, and CombatService routing \u2014 so the fairness and anti-exploit guarantees that apply to player guns (dodgeable travel time, no hitscan instakills, spread, range caps) apply identically to enemy fire. An archetype only becomes armed if it has a matching EnemyCombatConfig profile; archetypes without one spawn and walk around (via EnemySpawner) but never fire.","sidebar":"docs"},"systems/enemy-spawner":{"id":"systems/enemy-spawner","title":"Enemy Spawner","description":"A generic, server-authoritative combatant spawner for the pirate-encounter and outpost gameplay loops. Given a named spawn group and a wave request, EnemySpawner selects attachment-authored spawn points with cumulative-inverse weighting, jitters each position within a configurable disc, validates the candidate through SpawnVerification (ground snap, wall/headroom clearance, enemy spacing), clones the archetype Model from ServerStorage.EnemyAssets, and returns a WaveHandle that fires OnCleared once the last enemy dies. The server is the sole authority; spawned Models replicate to clients natively via Roblox replication \u2014 no packets are required. The spawner owns only the act of spawning: it does not implement AI/pathfinding, manage the cutscene/boarding state machine, or model outpost-stop trigger detection. Orchestrators call SpawnWave and react to WaveHandle.OnCleared.","sidebar":"docs"},"systems/events-orchestrator":{"id":"systems/events-orchestrator","title":"Events Orchestrator","description":"A server-authoritative scheduler that decides when in-game events fire, which event fires, and enforces a configurable gap between events. It drives a virtual odometer (distance the train has traveled, accumulated only while running) and one independent state machine per channel. Each channel rolls a weighted table at a configurable distance cadence; the roll can come up empty (a Nothing entry), with a pity guard that forces a real event after enough empty rolls. Events plug in as handler modules implementing a shared EventHandler interface \u2014 the orchestrator never touches networking; each handler owns its own client communication.","sidebar":"docs"},"systems/grabhook":{"id":"systems/grabhook","title":"GrabHook","description":"The GrabHook is a player tool that fires a tethered hook to collect floating junk. The client owns all raycasting and rope visuals; the server validates the claim and awards the item.","sidebar":"docs"},"systems/health":{"id":"systems/health","title":"Health","description":"The server is the single source of truth for every player\'s health value. HealthManager maintains an internal record, drives regen on RunService.Heartbeat, mirrors values to the Roblox Humanoid, and broadcasts to the owning client via HealthStateSync. The client forwards that packet to a signal consumed by the HUD.","sidebar":"docs"},"systems/jump-drive":{"id":"systems/jump-drive","title":"Jump Drive","description":"A server-authoritative, player-initiated biome transition: a charge gauge fed by","sidebar":"docs"},"systems/junk":{"id":"systems/junk","title":"Junk","description":"The junk system spawns debris that floats past the train for players to collect with the GrabHook. The server owns spawning, weighted selection, and collection validation; the client renders junk with pooled instances and drives the movement simulation locally using a shared speed value.","sidebar":"docs"},"systems/notifications":{"id":"systems/notifications","title":"Notifications","description":"A client-side toast stack driven entirely by signals. Any controller fires one signal to show a notification; NotificationManager is the sole subscriber and handles all layout, animation, audio, and cleanup. There is no server component.","sidebar":"docs"},"systems/perks":{"id":"systems/perks","title":"Perks","description":"A level-driven permanent progression system, backed by ProfileStore, that lets players spend points on persistent buffs. Two independent point pools \u2014 Personal (buffs the owner only) and Party (buffs resolved as the server-max across all players) \u2014 each grow by exactly 1 point per XP level; points are derived, never stored. Every perk must be unlocked with a one-time coin + level gate before points can be spent on it \u2014 see Unlock gate. Respec is free to initiate and, unlike leveling, also re-locks and refunds unlocked perks. Structured shared/server/client exactly like Quests and Battle Pass.","sidebar":"docs"},"systems/placeable-actions":{"id":"systems/placeable-actions","title":"Placeable Actions (Stash / Move)","description":"Stash returns a placed item to the player\'s Backpack; Move does the same and immediately auto-equips it. Both actions are triggered by invisible ImageButtons inside the placeable\'s own GUI and validated server-side before any item is transferred.","sidebar":"docs"},"systems/placement":{"id":"systems/placement","title":"Placement","description":"The placement system lets players preview and place items in designated build areas. A shared validation module (PlacementSystem) runs identically on the client (preview) and server (authority) \u2014 the client predicts and previews instantly, and the server re-validates every placement before committing it.","sidebar":"docs"},"systems/progression":{"id":"systems/progression","title":"Progression (XP & Level)","description":"Server-authoritative, party-shared XP & Level system persisted with ProfileStore. Level and progress are always derived from a single stored lifetime value via a pure curve module, so re-tuning the curve never desyncs saved data.","sidebar":"docs"},"systems/proximity-pickup":{"id":"systems/proximity-pickup","title":"Proximity Pickup","description":"Dropped craft-material Tools and shredder-ejected material handles register with a server pickup system; any player who walks into the detection sphere claims the item. Unclaimed items auto-collect to the owner after a configurable delay. The client plays a hover/spin effect on unclaimed items and a float-to-hand animation on claim.","sidebar":"docs"},"systems/quests":{"id":"systems/quests","title":"Quests (Daily & Weekly)","description":"A rotating, ProfileStore-backed quest system layered on top of the coin/XP economy. Four buckets \u2014 Personal/Party \xd7 Daily/Weekly \u2014 rotate on a global, deterministic schedule so every player and server in a given period sees the same active quests. A fifth, non-rotating Season scope additionally feeds the Battle Pass. Progress is server-authoritative; rewards pay coins, exp, and an optional battle pass EXP feed. The system is split shared/server/client exactly like Perks.","sidebar":"docs"},"systems/research-bench":{"id":"systems/research-bench","title":"Research Bench","description":"A cooperative, server-wide, session-only (no DataStore) research system replaces the old Tech Tree. Players pay materials up front to enqueue a node\'s next level at one fixed bench; a single active job advances over real time, gated by a shared fuel reserve that only drains while a job is progressing. Nodes are leveled (1..MaxLevel, each level re-payable and re-timed) rather than binary unlocks, and a node with no Effect is a pure recipe node \u2014 it exists only to gate a Workbench recipe via the ResearchUnlocked folder.","sidebar":"docs"},"systems/session-rejoin":{"id":"systems/session-rejoin","title":"Party Lock + Mid-Run Rejoin","description":"Two related guarantees for a live run, both enforced authoritatively on the serverTeleportMembers; this repo is the gameplay place on the receiving end. Persistent progression (XP, coins, perks) is unaffected \u2014 it\'s handled by ProfileStore independently of this system, which only concerns itself with a run\'s ephemeral, in-server state.","sidebar":"docs"},"systems/settings":{"id":"systems/settings","title":"Settings (User Preferences)","description":"A generic, server-authoritative user-preferences system. Every persisted preference \u2014 the four audio bus volumes (MasterVolume, MusicVolume, SFXVolume, AmbienceVolume) and CameraSensitivity today, anything else in the future \u2014 is one entry in a single typed registry, validated by one shared schema, and synced/saved through one packet pair. There is no per-setting packet, no per-setting DataStore key, and no bespoke client-side state machine; adding a setting is a config-table edit, not a new subsystem.","sidebar":"docs"},"systems/shredder":{"id":"systems/shredder","title":"Shredder","description":"Players hold a ProximityPrompt on a placed Workbench to convert non-Energy junk Tools into crafting material Tools via a two-step server handshake; ejected materials land in the world with a bezier arc and hover until picked up or auto-collected.","sidebar":"docs"},"systems/sound":{"id":"systems/sound","title":"Sound","description":"A layered client audio system built around a single facade module, SoundManager. All game audio \u2014 one-shot SFX, positional SFX, looped sounds, background music, and ambience beds \u2014 flows through it; no other script creates Sound instances directly. Playback is entirely client-local except for positional SFX replication and BGM context, which are server-relayed/server-driven through Packets.","sidebar":"docs"},"systems/stamina-sprint":{"id":"systems/stamina-sprint","title":"Stamina & Sprint","description":"Sprint is client-predicted for responsive feel and server-authoritative for integrity. The client applies WalkSpeed/FOV changes instantly on input; the server runs the canonical stamina simulation and pushes syncs at up to 10 Hz, which the client uses to gate visual and audio effects.","sidebar":"docs"},"systems/train-fuel":{"id":"systems/train-fuel","title":"Train Fuel","description":"A single global fuel value (0\u2013100) governs the train\'s Running/Braked/Stalled state for all players. The server computes fuel algebraically from the timestamp of the last event rather than polling every frame; every state transition snapshots the current fuel, switches the drain rate, and schedules the next deterministic transition via a nonce-guarded task.delay. Clients receive a snapshot and predict the bar locally between events \u2014 TrainFuelManager is the sole authority.","sidebar":"docs"},"systems/train-shield":{"id":"systems/train-shield","title":"Train Shield","description":"A single global shield pool governs the train\'s structural integrity for all players. Unlike fuel, the shield has no continuous drain \u2014 it is event-driven: damage events deplete it, and players restore it by feeding Energy tools into a ShieldConsole. Depleting the shield to 0 is no longer a game over; once the shield is down, further attacks bleed through to fuel instead. TrainShieldManager is the sole authority \u2014 clients receive snapshots and update the diegetic shield monitor.","sidebar":"docs"},"systems/weapons":{"id":"systems/weapons","title":"Weapons","description":"Client-predicts / server-authoritative combat with a shared validator (WeaponValidation). All damage is applied server-side; client hit claims are never trusted. Weapons are Roblox Tools equipped from the Backpack; the server infers the weapon from the equipped Tool, so fire packets carry only origin/direction \u2014 never a claimed target.","sidebar":"docs"},"systems/workbench-crafting":{"id":"systems/workbench-crafting","title":"Workbench Crafting","description":"A placed Workbench station lets players craft weapons, armor, and placeables from config-defined recipes in a single server-authoritative round-trip. Crafting is instant (no hold duration) and per-player. The station is placed in the world by the existing placement system and interacted with through a ProximityPrompt; Stash/Move of the Workbench itself is handled by the existing Placeable Actions system.","sidebar":"docs"}}}}')}}]);